create extension if not exists pgcrypto;
create type user_role as enum ('USER','ADMIN');
create table profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text not null,role user_role not null default 'USER',balance integer not null default 1000,created_at timestamptz not null default now());
create function handle_new_user() returns trigger as $$ begin insert into public.profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'display_name',split_part(new.email,'@',1))); return new; end; $$ language plpgsql security definer set search_path=public;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure handle_new_user();
create table players(id uuid primary key default gen_random_uuid(),name text not null,image_url text not null,game text not null default 'TDM',power integer not null check(power between 1 and 100),speed integer not null check(speed between 1 and 100),defense integer not null check(defense between 1 and 100),active boolean not null default true,created_by uuid references profiles(id),created_at timestamptz not null default now());
create type match_status as enum ('PENDING','RESOLVED');
create table matches(id uuid primary key default gen_random_uuid(),mode text not null default 'TDM_1V1',player_a_id uuid not null references players(id),player_b_id uuid not null references players(id),winner_id uuid references players(id),status match_status not null default 'PENDING',resolved_at timestamptz,created_at timestamptz not null default now(),check(player_a_id<>player_b_id));
create type bet_status as enum ('PENDING','WON','LOST');
create table bets(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles(id),match_id uuid not null references matches(id),player_id uuid not null references players(id),amount integer not null check(amount>0),payout integer,status bet_status not null default 'PENDING',created_at timestamptz not null default now());
alter table profiles enable row level security; alter table players enable row level security; alter table matches enable row level security; alter table bets enable row level security;
create function is_admin(uid uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profiles where id=uid and role='ADMIN') $$;
create policy profiles_select_own on profiles for select using(auth.uid()=id or is_admin(auth.uid()));
create policy profiles_update_name on profiles for update using(auth.uid()=id) with check(auth.uid()=id);
create policy players_select_active on players for select using(active=true or is_admin(auth.uid()));
create policy players_admin_all on players for all using(is_admin(auth.uid())) with check(is_admin(auth.uid()));
create policy bets_select_own_admin on bets for select using(user_id=auth.uid() or is_admin(auth.uid()));
create policy matches_select_related on matches for select using(is_admin(auth.uid()) or exists(select 1 from bets where bets.match_id=matches.id and bets.user_id=auth.uid()));
create function place_and_resolve_bet(p_user_id uuid,p_player_a_id uuid,p_player_b_id uuid,p_backed_player_id uuid,p_amount integer) returns table(bet_id uuid,match_id uuid,winner_id uuid,status bet_status,payout integer,new_balance integer) language plpgsql security definer set search_path=public as $$ declare bal integer; a players%rowtype; b players%rowtype; score_a numeric; score_b numeric; win uuid; m_id uuid; b_id uuid; out_status bet_status; out_payout integer; begin if p_amount<=0 then raise exception 'Bet amount must be positive'; end if; if p_player_a_id=p_player_b_id then raise exception 'Players must be different'; end if; if p_backed_player_id not in (p_player_a_id,p_player_b_id) then raise exception 'Backed player must be in matchup'; end if; select balance into bal from profiles where id=p_user_id for update; if bal is null then raise exception 'Profile not found'; end if; if p_amount>bal then raise exception 'Insufficient balance'; end if; select * into a from players where id=p_player_a_id and active=true and game='TDM'; select * into b from players where id=p_player_b_id and active=true and game='TDM'; if a.id is null or b.id is null then raise exception 'Active TDM players required'; end if; update profiles set balance=balance-p_amount where id=p_user_id; score_a:=a.power*.4+a.speed*.3+a.defense*.3; score_b:=b.power*.4+b.speed*.3+b.defense*.3; win:=case when random() < (score_a/(score_a+score_b)) then a.id else b.id end; insert into matches(player_a_id,player_b_id,winner_id,status,resolved_at) values(a.id,b.id,win,'RESOLVED',now()) returning id into m_id; out_status:=case when p_backed_player_id=win then 'WON'::bet_status else 'LOST'::bet_status end; out_payout:=case when out_status='WON' then p_amount*2 else 0 end; insert into bets(user_id,match_id,player_id,amount,payout,status) values(p_user_id,m_id,p_backed_player_id,p_amount,out_payout,out_status) returning id into b_id; if out_payout>0 then update profiles set balance=balance+out_payout where id=p_user_id; end if; select balance into new_balance from profiles where id=p_user_id; bet_id:=b_id; match_id:=m_id; winner_id:=win; status:=out_status; payout:=out_payout; return next; end; $$;
